grant select,insert on fiscal_test_results to authenticated,anon;
update public.business_modules set enabled=true where module='management' and business_id='be660000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ae660000-0000-4000-8000-000000000001","role":"authenticated"}',true);
reset role;
update public.business_modules set enabled=true where module='fiscal' and business_id='be660000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ae660000-0000-4000-8000-000000000002","role":"authenticated"}',true);
reset role;
select result from fiscal_test_results;
rollback;
